const D = { layers: 4, scale: 1, energy: .6, density: .5, hue: 34, speed: 1, x: .3, y: .5, alpha: 1, style: 'encaustic', act: 'fuse', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height;
const sty=P.style, act=P.act;
const nLp=cl(P.layers,1,6), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=190, BH=cl(Math.round(BW*Hh/Math.max(1,W)),56,190);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; S.h=new Float32Array(BW*BH); S.ht=new Float32Array(BW*BH); }
const G=S.g, HF=S.h, HT=S.ht;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let nL=Math.round(nLp), gunR=1, scrape=0;
if(act==='build'){ nL=Math.max(1,Math.round(1+(nLp-1)*(.35+.65*(.5+.5*Math.sin(sec*.72+T*.015))))); gunR=1.15; }
else if(act==='scrape'){ scrape=.45+.45*Math.sin(sec*.85+T*.021); gunR=.7; }

// ---- the heat gun: it orbits the panel, and where it passes the wax goes molten —
// stroke edges bleed, the surface levels and comes up wet. A monotonic angle, plus a
// second incommensurate epicycle so the pass never exactly repeats.
const gAng=.052*TD*gunR, gAng2=.131*TD*gunR+2.1;
const gx0=.52*Math.cos(gAng)+.19*Math.cos(gAng2), gy0=.33*Math.sin(gAng)+.13*Math.sin(gAng2);
const gunRad=(.30+.20*dens)*Math.max(.5,sc);
// the wax never fully sets — every layer creeps, the deep ones slower. Monotonic: the
// motion floor cannot re-phase away.
const flow=.055*TD;
// raking studio light on the buffed surface
const lAz=cl(P.x,0,1)*TAU + .0125*TD + .24*Math.sin(TD*.047+.4) + .12*Math.sin(TD*.103+2.2);
const lx=Math.cos(lAz), ly=Math.sin(lAz);
const lEl=(cl(P.y,0,1)-.5)*1.2 + .14*Math.sin(TD*.061+1.1) + .06*Math.sin(TD*.131+2.6) + .03*K.swell;

// ---- style ----
let GROUND, WAX, spTint, relief=0, milkK=1, satK=1, glossK=1;
if(sty==='cold_wax'){ GROUND=hsb2rgb(H-8,16,26); WAX=hsb2rgb(H+6,10,58); spTint=[250,246,236]; milkK=.55; satK=.72; glossK=.42; }
else if(sty==='resin'){ GROUND=hsb2rgb(H+180,30,12); WAX=hsb2rgb(H+4,6,70); spTint=[255,255,255]; milkK=.42; satK=1.25; glossK=2.1; }
else if(sty==='relief'){ GROUND=hsb2rgb(H,4,42); WAX=hsb2rgb(H,3,52); spTint=[255,252,245]; relief=1; milkK=0; satK=0; glossK=1.5; }
else if(sty==='nocturne'){ GROUND=hsb2rgb(H+200,44,7); WAX=hsb2rgb(H+196,26,26); spTint=[210,224,255]; milkK=.75; satK=.55; glossK=1.3; }
else { GROUND=hsb2rgb(H-10,22,34); WAX=hsb2rgb(H+8,13,80); spTint=[255,248,230]; milkK=1; satK=1; glossK=1; }

// ---- the palette: a seeded set of pigments the painter is actually working with ----
const NPL=8, plK=P.seed+'|'+sty+'|'+Math.round(H)+'|'+Math.round(satK*10);
if(S.plK!==plK){ S.plK=plK; const PL=new Float32Array(NPL*3);
  for(let k=0;k<NPL;k++){
    const r1=fr(k*4.3+700), r2=fr(k*4.3+701), r3=fr(k*4.3+702);
    let hh,ss,bb;
    if(sty==='nocturne'){ hh=H+180+r1*90; ss=(14+40*r2)*satK; bb=8+40*r3; }
    else if(sty==='resin'){ hh=H+r1*300; ss=(45+50*r2)*satK; bb=26+56*r3; }
    else { // a working palette: two earths, a saturated accent, a near-black, a bone white
      const p=r1;
      if(p<.30){ hh=H-6+r2*22; ss=(38+30*r2)*satK; bb=32+30*r3; }        // earth
      else if(p<.52){ hh=H+r2*30-10; ss=(58+34*r2)*satK; bb=44+34*r3; }  // warm accent
      else if(p<.70){ hh=H+165+r2*70; ss=(40+40*r2)*satK; bb=26+34*r3; } // cool complement
      else if(p<.86){ hh=H+8+r2*16; ss=(5+10*r2)*satK; bb=72+22*r3; }    // bone / wax white
      else { hh=H+10+r2*40; ss=(20+30*r2)*satK; bb=6+12*r3; }            // near-black
    }
    const c=hsb2rgb(hh,ss,bb); PL[k*3]=c[0]; PL[k*3+1]=c[1]; PL[k*3+2]=c[2];
  }
  S.pl=PL; }
const PL=S.pl;

const asp=W/Math.max(1,Hh);
const sf=1.55/Math.max(.35,sc);
// per-layer constants: hoisted OUT of the pixel loop. Calling the seeded hash per layer
// per pixel cost ~490k Math.sin/frame and dominated the whole asset.
const LA=new Float32Array(nL*8);
for(let L=0;L<nL;L++){
  LA[L*8]=(md(Math.floor(fr(L*2.7+800)*NPL),NPL)|0)*3;
  LA[L*8+1]=fr(L*2.7+801)*17.3;
  LA[L*8+2]=fr(L*2.7+802)*11.9;
  LA[L*8+3]=flow*(.40+.60*(L+1)/nL);
  LA[L*8+4]=.72+.28*fr(L*2.7+803);
  LA[L*8+5]=.030+.030*fr(L*2.7+804);
  LA[L*8+6]=(.070+.075*fr(L*2.7+805))*milkK;
  LA[L*8+7]=.72-.24*dens+(scrape>0?scrape*.42*((L+1)/nL):0);
}
const camX=.010*Math.sin(TD*.039+.7), camY=.010*Math.cos(TD*.053+2.4);

// ---- PASS 1: composite the layers bottom-up, veiling each with its own clear wax ----
G.loadPixels();
const px=G.pixels;
for(let j=0;j<BH;j++){
  const sy=(j/BH-.5)+camY;
  for(let i=0;i<BW;i++){
    const sx=(i/BW-.5)*asp+camX;
    const dgx=sx-gx0, dgy=sy-gy0;
    const heat=Math.exp(-(dgx*dgx+dgy*dgy)/(gunRad*gunRad));
    HT[j*BW+i]=heat;
    let R=GROUND[0], Gc=GROUND[1], B=GROUND[2], hh=0;
    const soft=.030+.30*heat+.04*(1-dens), isoft=1/(2*soft);
    for(let L=0;L<nL;L++){
      const b=L*8, pi=LA[b], cr=LA[b+3];           // upper layers creep faster
      const fx=sx*sf+LA[b+1]+cr, fy=sy*sf+LA[b+2]+cr*.6;
      const n1=nzAt(fx,fy), n2=nzAt(fx*2.7+11.1, fy*2.7+7.3);
      const raw=n1*.78+n2*.34;
      // heat bleeds the stroke edge; a scrape act cuts the upper layers back
      let cov=cl((raw-(LA[b+7]-soft))*isoft,0,1); cov=cov*cov*(3-2*cov);
      cov*=LA[b+4];
      if(cov>0){
        R=R*(1-cov)+PL[pi]*cov; Gc=Gc*(1-cov)+PL[pi+1]*cov; B=B*(1-cov)+PL[pi+2]*cov;
        hh+=cov*LA[b+5];                           // wax builds where the stroke sits
      }
      // this layer's clear wax veils everything already down — depth reads as milk
      const veil=LA[b+6];
      R=R*(1-veil)+WAX[0]*veil; Gc=Gc*(1-veil)+WAX[1]*veil; B=B*(1-veil)+WAX[2]*veil;
      hh+=.012;
    }
    // molten wax levels itself — the gun flattens the topography where it passes
    hh*=(1-.55*heat);
    HF[j*BW+i]=hh;
    const o=(j*BW+i)*4;
    px[o]=R; px[o+1]=Gc; px[o+2]=B; px[o+3]=255;
  }
}

// ---- PASS 2: surface. Satin sheen off the wax topography, wet gloss where it is molten.
const sR=spTint[0], sG=spTint[1], sB=spTint[2];
const NG=52;
const spAmt=(.20+.85*en)*glossK*(.6+.6*K.intensity)+S.tre*.25*en;
for(let j=0;j<BH;j++){
  const j0=Math.max(0,j-1)*BW, j1=Math.min(BH-1,j+1)*BW, jr=j*BW;
  for(let i=0;i<BW;i++){
    const idx=jr+i, o=idx*4;
    const nx=-(HF[jr+Math.min(BW-1,i+1)]-HF[jr+Math.max(0,i-1)])*.5*NG;
    const ny=-(HF[j1+i]-HF[j0+i])*.5*NG;
    const nl=1/Math.sqrt(nx*nx+ny*ny+1);
    const Nx=nx*nl, Ny=ny*nl, Nz=nl;
    const heat=HT[idx];
    const lam=cl(.52+(Nx*lx+Ny*ly)*.85+Nz*.12,.14,1.5);
    // sheen: tight where the wax is molten and levelling, broad on set wax
    const hn=cl(Nx*lx+Ny*ly-lEl*.55,-3,3);
    const tight=2.4+7.0*heat;
    const spec=spAmt*(.35+1.5*heat)/(1+hn*hn*tight*tight);
    let R=px[o], Gc=px[o+1], B=px[o+2];
    if(relief){ // the wax topography alone, no pigment — a raking survey of the surface
      const v=cl(.30+lam*.62,0,1.4);
      R=GROUND[0]*v; Gc=GROUND[1]*v; B=GROUND[2]*v;
    } else { R*=(.46+.62*lam); Gc*=(.46+.62*lam); B*=(.46+.62*lam); }
    const s2=spec*70;
    R+=sR*s2/255; Gc+=sG*s2/255; B+=sB*s2/255;
    // the molten pass glows faintly warm through the wax
    if(!relief){ const gl=heat*heat*22*(.4+.6*en); R+=gl*1.0; Gc+=gl*.62; B+=gl*.28; }
    const vx=(i/BW-.5), vy=(j/BH-.5), vg=1-.30*(vx*vx*1.1+vy*vy*1.5);
    R*=vg; Gc*=vg; B*=vg;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
const dc=drawingContext;
blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
